-- Phase 30 S4: add geo_scope/city fields + seed Auckland RE / Brisbane Flooring / NZ 3PL

alter table baseline_domains
  add column if not exists city       text,
  add column if not exists geo_scope  text
    check (geo_scope in ('city','state','national'));

alter table baseline_domains drop constraint if exists baseline_domains_sub_industry_domain_key;
alter table baseline_domains
  add constraint baseline_domains_sub_industry_city_domain_key
  unique (sub_industry, city, domain);

update baseline_domains set geo_scope = 'national', city = null where geo_scope is null;

-- real_estate_auckland
on conflict (sub_industry,city,domain) do nothing;

-- flooring_tiles_brisbane
on conflict (sub_industry,city,domain) do nothing;

-- logistics_3pl_nz
on conflict (sub_industry,city,domain) do nothing;
